      if (GetCoins() < sRoulette.minBet)
          gSpecialVar_0x8004 = TRUE;
      else
          gSpecialVar_0x8004 = FALSE;
      TryPutFindThatGamerOnAir(GetCoins());
      BeginHardwarePaletteFade(0xFF, 0, 0, 16, 0);
